import os

input_files = ["input_1.txt", "input_6.txt"]

def pattern_count(text, pattern):
    count = 0
    for i in range(len(text) - len(pattern) + 1):
        if text[i:i+len(pattern)] == pattern:
            count += 1
    return count

text= "ATGCATTCATCG"
pattern= "TC"
print("pattern count of text=ATGCATTCATCG, pattern=TC is:", pattern_count(text, pattern))
